    "sec02_coverStory": {
      "sectionTitle": "BÀI ĐINH TRANG NHẤT · COVER STORY",
      "editorialHeadline": "Tỷ giá trung tâm lập đỉnh mới 25.659 đồng, Quốc hội nâng chuẩn SME lên 400 tỷ và khối ngoại bán ròng kỷ lục 126.000 tỷ",
      "editorialSubheadline": "Sáng 20/11, tỷ giá trung tâm tăng 13 đồng giữa lúc DXY lên 103,88 điểm trước kỳ vọng Fed nâng lãi suất ba lần; Quốc hội thông qua Luật Phát triển SME và Basel cảnh báo rủi ro AI ngân hàng.",
      "dek": "Áp lực tỷ giá và dòng vốn ngoại rút kỷ lục đang định hình lại mặt bằng chi phí vốn cuối năm, đồng thời mở ra dư địa ưu đãi thuế cho nhóm doanh nghiệp nhỏ và vừa từ đầu năm 2027.",
      "executiveSummary": "Sáng 20/11, NHNN nâng tỷ giá trung tâm thêm 13 đồng lên đỉnh mới 25.659 VND/USD khi DXY chạm 103,88 điểm. Cùng buổi sáng, Quốc hội thông qua Luật Phát triển SME nâng ngưỡng doanh thu xác định lên 400 tỷ đồng từ 2027. Trên HoSE, khối ngoại bán ròng lũy kế đạt 126.000 tỷ đồng.",
      "leadArticle": {
        "headline": "Tỷ giá USD hôm nay 20/11: Tỷ giá trung tâm lập đỉnh mới 25.659 đồng, thị trường đặt cược Fed tăng lãi suất ba lần",
        "eventId": "EVT-29",
        "sourceName": "Thời báo Tài chính Việt Nam",
        "publishedAt": "20/11/2026 08:53 | Nguồn gốc: Thời báo Tài chính Việt Nam (2026-11-20T08:53:49+07:00)",
        "sourceUrl": "https://thoibaotaichinhvietnam.vn/ty-gia-usd-hom-nay-20-11-ty-gia-trung-tam-lap-dinh-moi-25-659-dong-thi-truong-dat-cuoc-fed-tang-lai-suat-ba-lan-207252.html",
        "summary": "Sáng 20/11, NHNN nâng tỷ giá trung tâm thêm 13 đồng lên đỉnh mới 25.659 VND/USD khi DXY chạm 103,88 điểm. Cùng buổi sáng, Quốc hội thông qua Luật Phát triển SME nâng ngưỡng doanh thu xác định lên 400 tỷ đồng từ 2027. Trên HoSE, khối ngoại bán ròng lũy kế đạt 126.000 tỷ đồng.",
        "supportingQuote": "Với biên độ 5%, tỷ giá USD tại các ngân hàng thương mại sáng 20/11 được phép giao dịch trong khoảng 24.376,05 đến 26.941,95 VND/USD trong khi giá bán tại Vietcombank lên 25.940 đồng.",
        "imageUrl": "https://thoibaotaichinhvietnam.vn/stores/news_dataimages/2026/112026/13/22/in_social/ty-gia-final20261113222351.jpg?v=2.720260812095833"
      },
      "imageUrl": "https://thoibaotaichinhvietnam.vn/stores/news_dataimages/2026/112026/13/22/in_social/ty-gia-final20261113222351.jpg?v=2.720260812095833",
      "supportingQuote": "Với biên độ 5%, tỷ giá USD tại các ngân hàng thương mại sáng 20/11 được phép giao dịch trong khoảng 24.376,05 đến 26.941,95 VND/USD trong khi giá bán tại Vietcombank lên 25.940 đồng.",
      "editorialPullQuote": "Với biên độ 5%, tỷ giá USD tại các ngân hàng thương mại sáng 20/11 được phép giao dịch trong khoảng 24.376,05 đến 26.941,95 VND/USD trong khi giá bán tại Vietcombank lên 25.940 đồng.",
      "pullQuote": "Với biên độ 5%, tỷ giá USD tại các ngân hàng thương mại sáng 20/11 được phép giao dịch trong khoảng 24.376,05 đến 26.941,95 VND/USD trong khi giá bán tại Vietcombank lên 25.940 đồng.",
      "editorialSynthesis": "Toàn cảnh phiên 20/11/2026 hội tụ bốn mạch chuyển động trọng yếu từ 40 sự kiện xác minh: (1) Tỷ giá lập đỉnh lịch sử mới và kỳ vọng thắt chặt từ Fed: NHNN công bố tỷ giá trung tâm sáng 20/11 tăng 13 đồng lên 25.659 VND/USD (VCB 25.530–25.940; tự do 26.140–26.190) trong bối cảnh DXY đạt 103,88 điểm khi thị trường đặt cược Fed tăng lãi suất 3 kỳ họp liên tiếp; (2) Quốc hội bấm nút thông qua Luật Phát triển SME và chuẩn vốn ngân hàng mới: Sáng 20/11, 100% đại biểu biểu quyết thông qua luật nâng ngưỡng doanh thu SME lên 400 tỷ đồng và đề xuất giảm phạt thuế 12.671 tỷ đồng cho 2,5 triệu người nộp thuế, song hành cùng thống kê 9 nhà băng vượt mốc tổng tài sản 1 triệu tỷ đồng; (3) Chứng khoán kiểm định vùng dưới 1.700 điểm trước kỷ lục bán ròng ngoại: Kết phiên liền trước, VN-Index lùi về 1.689,62 điểm và Dow Jones mất hơn 1.100 điểm bất chấp Anthropic tạo kỷ lục IPO 81 tỷ USD, đẩy P/E thị trường Việt Nam về 10,8 lần; (4) Thanh toán số nâng cấp lớp phòng thủ trước lừa đảo QR và lỗ hổng AI: Công an Đồng Nai cảnh báo thủ đoạn gửi mã QR giả hoàn tiền chuyển nhầm, Calif cùng OpenAI dùng GPT-6 Cyber phát hiện 35 lỗ hổng Apple trong khi MoMo đẩy kích cầu Vibrant HCMC.",
      "marketImpact": "(1) Gia tăng chi phí nhập khẩu và nhu cầu hedging ngoại hối: Độ trễ thanh toán L/C 1–3 tháng dễ xóa sạch biên lợi nhuận nếu doanh nghiệp không sử dụng hợp đồng kỳ hạn ngoại tệ. (2) Mở rộng tệp SME hưởng ưu đãi thuế và tín dụng: Nâng trần doanh thu SME từ 300 lên 400 tỷ đồng giúp nhiều doanh nghiệp tăng trưởng cao tiếp cận cơ chế hỗ trợ vốn năm 2027. (3) Sức ép định giá cổ phiếu vốn hóa lớn: Lực bán ròng 126.000 tỷ đồng trên HoSE tạo chênh lệch giữa tăng trưởng lợi nhuận niêm yết (+43% quý III) và mặt bằng giá cổ phiếu.",
      "fintechLensAction": "Biến động tỷ giá USD lên vùng đỉnh mới cùng làn sóng 12 ngân hàng điều chỉnh tăng lãi suất cho vay tháng 10 đòi hỏi bộ phận tài chính doanh nghiệp tự động hóa đối soát công nợ đa kênh. Tích hợp cổng thanh toán không tiền mặt, trích xuất hóa đơn chuẩn hóa qua AI và dịch vụ quy đổi ngoại tệ minh bạch giúp điểm bán tối ưu dòng tiền và triệt tiêu rủi ro giả mạo mã QR.",
      "monitoringWatchpoint": "Theo dõi diễn biến tỷ giá bán USD tại nhóm ngân hàng quốc doanh quanh mốc trần biên độ, phiên họp Quốc hội biểu quyết nghị quyết nợ thuế ngày 20–21/11 và vùng cân bằng mới của VN-Index dưới mốc 1.700 điểm.",
      "whyItMatters": "(1) Gia tăng chi phí nhập khẩu và nhu cầu hedging ngoại hối: Độ trễ thanh toán L/C 1–3 tháng dễ xóa sạch biên lợi nhuận nếu doanh nghiệp không sử dụng hợp đồng kỳ hạn ngoại tệ. (2) Mở rộng tệp SME hưởng ưu đãi thuế và tín dụng: Nâng trần doanh thu SME từ 300 lên 400 tỷ đồng giúp nhiều doanh nghiệp tăng trưởng cao tiếp cận cơ chế hỗ trợ vốn năm 2027. (3) Sức ép định giá cổ phiếu vốn hóa lớn: Lực bán ròng 126.000 tỷ đồng trên HoSE tạo chênh lệch giữa tăng trưởng lợi nhuận niêm yết (+43% quý III) và mặt bằng giá cổ phiếu.",
      "keyMarketImplication": "Biến động tỷ giá USD lên vùng đỉnh mới cùng làn sóng 12 ngân hàng điều chỉnh tăng lãi suất cho vay tháng 10 đòi hỏi bộ phận tài chính doanh nghiệp tự động hóa đối soát công nợ đa kênh. Tích hợp cổng thanh toán không tiền mặt, trích xuất hóa đơn chuẩn hóa qua AI và dịch vụ quy đổi ngoại tệ minh bạch giúp điểm bán tối ưu dòng tiền và triệt tiêu rủi ro giả mạo mã QR."
    },
