      "sectionC_whyItMatters": "Các chuẩn mực thanh khoản toàn cầu sau nhiều năm vận hành đang được tinh chỉnh để phản ánh tốc độ rút tiền trực tuyến ngày càng nhanh.",
      "sectionD_macroMicro": "Ủy ban Basel chỉ rõ việc đẩy mạnh dịch vụ điện toán đám mây và bên thứ ba công nghệ làm gia tăng nguy cơ gián đoạn dịch vụ tài chính thiết yếu.",
      "sectionE_fintechLens": "Lựa chọn nhà cung cấp hạ tầng thanh toán đạt chuẩn an toàn vận hành và dự phòng đa vùng giúp ngân hàng đáp ứng sớm khuyến nghị quốc tế.",
